def load_public_matrix(path: str | Path) -> list[list[int]]:
    """Parse Sage's compressed pickle without requiring SageMath."""
    raw = zlib.decompress(Path(path).read_bytes())
    packed = next(
        arg
        for opcode, arg, _ in pickletools.genops(raw)
        if opcode.name == "BINUNICODE"
        and isinstance(arg, str)
        and len(arg) > 100_000
    )
    values = [int(token, 32) for token in packed.split()]
    n = 144
    if len(values) != n * n:
        raise ValueError(f"unexpected public matrix size: {len(values)}")
    return [values[i * n : (i + 1) * n] for i in range(n)]


def target_integer() -> int:
    from hashlib import sha256

    return int.from_bytes(b"\x01" + sha256(TARGET_MESSAGE).digest(), "big")


def quadratic_form(vector: list[int], matrix: list[list[int]]) -> int:
    return sum(
        vector[i] * sum(matrix[i][j] * vector[j] for j in range(144))
        for i in range(144)
    )


def verify_local(pk_path: str | Path) -> None:
    if len(SIGNATURE) != 144:
        raise ValueError(f"signature has {len(SIGNATURE)} entries, expected 144")
    matrix = load_public_matrix(pk_path)
    actual = quadratic_form(SIGNATURE, matrix)
    expected = target_integer()
    if actual != expected:
        raise ValueError("embedded signature does not verify")
    print("[+] Local verification passed")


def receive_available(sock: socket.socket, timeout: float = 2.0) -> bytes:
    sock.settimeout(timeout)
    chunks: list[bytes] = []
    while True:
        try:
            chunk = sock.recv(65536)
        except socket.timeout:
            break
        if not chunk:
            break
        chunks.append(chunk)
    return b"".join(chunks)


def exploit(host: str, port: int, timeout: float) -> str:
    payload = " ".join(map(str, SIGNATURE)).encode() + b"\n"

    with socket.create_connection((host, port), timeout=timeout) as sock:
        banner = receive_available(sock, timeout=1.0)
        if banner:
            sys.stdout.write(banner.decode(errors="replace"))
            sys.stdout.flush()

        sock.sendall(payload)
        response = receive_available(sock, timeout=timeout).decode(errors="replace")

    print(response, end="" if response.endswith("\n") else "\n")
    match = re.search(r"SEKAI\{[^}]+\}", response)
    if not match:
        raise RuntimeError("server response did not contain a SEKAI flag")

    flag = match.group(0)
    print(f"<FLAG>{flag}</FLAG>")
    return flag


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--host", default=DEFAULT_HOST)
    parser.add_argument("--port", type=int, default=DEFAULT_PORT)
    parser.add_argument("--timeout", type=float, default=10.0)
    parser.add_argument("--pk", default="pk.sobj")
    parser.add_argument(
        "--verify-only",
        action="store_true",
        help="verify the embedded signature locally and do not connect",
    )
    parser.add_argument(
        "--skip-local-verify",
        action="store_true",
        help="connect even when pk.sobj is not available locally",
    )
    args = parser.parse_args()

    if not args.skip_local_verify:
        verify_local(args.pk)
    if not args.verify_only:
        exploit(args.host, args.port, args.timeout)


if __name__ == "__main__":
    main()
